-- ------------------------------------------------------
-- beDBug forward engineering script
-- Target engine: PostgreSQL
-- ------------------------------------------------------

CREATE TYPE "customer_status_enum" AS ENUM ('active', 'inactive');

CREATE TABLE "public"."customer" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" varchar(80) NOT NULL,
  "email" varchar(255) NOT NULL UNIQUE,
  "status" customer_status_enum NOT NULL DEFAULT 'active',
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

COMMENT ON TABLE "public"."customer" IS 'Customer master data.';

COMMENT ON COLUMN "public"."customer"."created_at" IS 'Row creation time.';

CREATE TABLE "public"."orders" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "customer_id" bigint NOT NULL,
  "total" numeric(12,2) NOT NULL DEFAULT 0,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

ALTER TABLE "public"."orders"
  ADD CONSTRAINT "fk_orders_customer" FOREIGN KEY ("customer_id")
  REFERENCES "public"."customer" ("id") ON DELETE CASCADE ON UPDATE RESTRICT;

CREATE INDEX "ix_customer_created_at" ON "public"."customer" ("created_at");
